import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        String s = next();
        int n = s.length();
        long answer = 0;
        // counts: letter frequencies of the suffix s[i..]
        long[] counts = new long[26];
        counts[s.charAt(n - 1) - 'a'] = 1;
        for (int i = n - 2; i >= 0; i--) {
            int c = s.charAt(i) - 'a';
            if (s.charAt(i) == s.charAt(i + 1)) {
                // the pair spreads its letter over the whole suffix to its right
                answer += n - i - 1 - counts[c];
                Arrays.fill(counts, 0);
                counts[c] = n - i - 1;
            }
            counts[c]++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := next()
	n := len(s)
	var answer int64
	// counts: letter frequencies of the suffix s[i..]
	var counts [26]int64
	counts[s[n-1]-'a'] = 1
	for i := n - 2; i >= 0; i-- {
		c := s[i] - 'a'
		if s[i] == s[i+1] {
			// the pair spreads its letter over the whole suffix to its right
			answer += int64(n-i-1) - counts[c]
			counts = [26]int64{}
			counts[c] = int64(n - i - 1)
		}
		counts[c]++
	}
	fmt.Println(answer)
}
